#include <rns8/rns8.h>
#include <stdint.h>
_Static_assert(sizeof(rns8_allocation_domain_observation)==56,"allocation domain ABI");
_Static_assert(sizeof(rns8_allocation_observation)==136,"allocation observation ABI");
int main(void) {
  rns8_context_options options={0};
  rns8_context* ctx=0;
  rns8_allocation_observation observation={0};
  uint64_t epoch=99;
  options.struct_size=sizeof(options);options.abi_version=RNS8_ABI_VERSION;
  options.requested_backend=RNS8_BACKEND_CPU_REFERENCE;
  observation.struct_size=sizeof(observation);observation.abi_version=RNS8_ABI_VERSION;observation.epoch=99;
  if(rns8_create_context(-1,&options,&ctx)!=RNS8_SUCCESS)return 1;
  if(rns8_get_allocation_observation(ctx,&observation)!=RNS8_UNSUPPORTED_BACKEND || observation.epoch!=99)return 2;
  if(rns8_reset_allocation_peaks(ctx,&epoch)!=RNS8_UNSUPPORTED_BACKEND || epoch!=99)return 3;
  if(rns8_destroy_context(ctx)!=RNS8_SUCCESS)return 4;
  options.requested_backend=RNS8_BACKEND_HIP_DIRECT;ctx=0;
  if(rns8_create_context(0,&options,&ctx)!=RNS8_SUCCESS)return 5;
  if(rns8_get_allocation_observation(ctx,&observation)!=RNS8_SUCCESS)return 6;
  if(rns8_reset_allocation_peaks(ctx,&epoch)!=RNS8_SUCCESS)return 7;
  if(rns8_get_allocation_observation(ctx,&observation)!=RNS8_SUCCESS || observation.epoch!=epoch)return 8;
  if(observation.device.peak_bytes!=observation.device.live_bytes || observation.pinned_host.peak_bytes!=observation.pinned_host.live_bytes)return 9;
  return rns8_destroy_context(ctx)==RNS8_SUCCESS?0:10;
}

